export declare const CORE_TABLES_SQL = "\nCREATE TABLE IF NOT EXISTS meta (\n  key TEXT PRIMARY KEY,\n  value TEXT\n);\n\nCREATE TABLE IF NOT EXISTS records (\n  id TEXT PRIMARY KEY,\n  layer TEXT NOT NULL,\n  scope_kind TEXT NOT NULL,\n  repo TEXT,\n  title TEXT NOT NULL,\n  body TEXT NOT NULL,\n  tags TEXT NOT NULL DEFAULT '[]',\n  confidence REAL NOT NULL,\n  expires_at TEXT,\n  times_seen INTEGER NOT NULL DEFAULT 1,\n  times_recalled INTEGER NOT NULL DEFAULT 0,\n  success_after_recall INTEGER NOT NULL DEFAULT 0,\n  fail_after_recall INTEGER NOT NULL DEFAULT 0,\n  superseded_by TEXT,\n  status TEXT NOT NULL DEFAULT 'active',\n  origin TEXT,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  source TEXT,\n  -- Space-joined CJK bigrams of title+body+tags. The unicode61 tokenizer does\n  -- not segment CJK, so a run like \u88AB\u6C99\u7BB1\u62D2\u7EDD is one token and a query for \u6C99\u7BB1\n  -- could never match it; the bigram column (schema v2) restores mid-run recall.\n  cjk TEXT NOT NULL DEFAULT ''\n);\nCREATE INDEX IF NOT EXISTS records_layer_idx ON records(layer, status);\nCREATE INDEX IF NOT EXISTS records_updated_idx ON records(updated_at DESC);\n\nCREATE TABLE IF NOT EXISTS evidence (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  record_id TEXT NOT NULL REFERENCES records(id) ON DELETE CASCADE,\n  kind TEXT NOT NULL,\n  detail TEXT,\n  turn INTEGER,\n  at TEXT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS evidence_record_idx ON evidence(record_id);\n\nCREATE TABLE IF NOT EXISTS usage (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  record_id TEXT NOT NULL REFERENCES records(id) ON DELETE CASCADE,\n  session_id TEXT,\n  turn INTEGER,\n  step INTEGER,\n  score REAL,\n  injected_at TEXT NOT NULL,\n  outcome TEXT\n);\nCREATE INDEX IF NOT EXISTS usage_record_idx ON usage(record_id);\nCREATE INDEX IF NOT EXISTS usage_session_idx ON usage(session_id);\n\nCREATE TABLE IF NOT EXISTS signals (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id TEXT NOT NULL,\n  turn INTEGER,\n  step INTEGER,\n  kind TEXT NOT NULL,\n  tool TEXT,\n  detail TEXT,\n  at TEXT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS signals_session_idx ON signals(session_id, turn);\n\nCREATE TABLE IF NOT EXISTS tasks (\n  task_id TEXT PRIMARY KEY,\n  date TEXT,\n  project TEXT,\n  summary TEXT,\n  outcome TEXT,\n  duration_min REAL,\n  disturb_count INTEGER,\n  rework_rounds INTEGER,\n  lessons INTEGER,\n  tokens INTEGER\n);\n\nCREATE TABLE IF NOT EXISTS distill (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id TEXT,\n  turn INTEGER,\n  model TEXT,\n  prompt_hash TEXT,\n  tokens_in INTEGER,\n  tokens_out INTEGER,\n  created_count INTEGER,\n  timed_out INTEGER,\n  at TEXT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS distill_at_idx ON distill(at DESC);\n\nCREATE TABLE IF NOT EXISTS conflicts (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  winner_id TEXT,\n  loser_id TEXT,\n  reason TEXT,\n  at TEXT NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS proposals (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  kind TEXT NOT NULL,\n  record_id TEXT,\n  title TEXT,\n  rationale TEXT,\n  status TEXT NOT NULL DEFAULT 'open',\n  at TEXT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS proposals_status_idx ON proposals(status, at DESC);\n\n-- Frozen metric snapshots: the regression gate compares against these instead of\n-- rewriting baseline.md, which stays a human-owned, read-only document.\n-- Semantic index (optional, default off): one vector per record and model.\n-- hash is the content hash the vector was computed from, so a changed lesson\n-- is re-embedded and an unchanged one never costs a call again.\nCREATE TABLE IF NOT EXISTS embeddings (\n  record_id TEXT NOT NULL,\n  model TEXT NOT NULL,\n  dim INTEGER NOT NULL,\n  hash TEXT NOT NULL,\n  vector BLOB NOT NULL,\n  at TEXT NOT NULL,\n  PRIMARY KEY (record_id, model)\n);\n\nCREATE TABLE IF NOT EXISTS baseline_snapshots (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  at TEXT NOT NULL,\n  scope TEXT,\n  tasks INTEGER,\n  success_rate REAL,\n  avg_duration REAL,\n  avg_disturb REAL,\n  avg_rework REAL,\n  note TEXT\n);\n\nCREATE TABLE IF NOT EXISTS consolidate_runs (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  at TEXT NOT NULL,\n  project TEXT,\n  archived INTEGER,\n  decayed INTEGER,\n  conflicts INTEGER,\n  proposals INTEGER,\n  note TEXT\n);\n";
export declare const FTS_SQL = "\nCREATE VIRTUAL TABLE IF NOT EXISTS records_fts USING fts5(\n  title, body, tags, cjk,\n  content='records',\n  content_rowid='rowid',\n  tokenize='unicode61'\n);\n\nCREATE TRIGGER IF NOT EXISTS records_fts_ai AFTER INSERT ON records BEGIN\n  INSERT INTO records_fts(rowid, title, body, tags, cjk)\n    VALUES (new.rowid, new.title, new.body, new.tags, new.cjk);\nEND;\n\nCREATE TRIGGER IF NOT EXISTS records_fts_ad AFTER DELETE ON records BEGIN\n  INSERT INTO records_fts(records_fts, rowid, title, body, tags, cjk)\n    VALUES ('delete', old.rowid, old.title, old.body, old.tags, old.cjk);\nEND;\n\nCREATE TRIGGER IF NOT EXISTS records_fts_au AFTER UPDATE ON records BEGIN\n  INSERT INTO records_fts(records_fts, rowid, title, body, tags, cjk)\n    VALUES ('delete', old.rowid, old.title, old.body, old.tags, old.cjk);\n  INSERT INTO records_fts(rowid, title, body, tags, cjk)\n    VALUES (new.rowid, new.title, new.body, new.tags, new.cjk);\nEND;\n";
